export async function reportAndExit(err: unknown): Promise<never> {
  if (sentryReady) {
    Sentry.captureException(err);
    await Sentry.flush(2_000);
  }
  process.stderr.write(`error: ${(err as Error).message}\n`);
  process.exit(1);
}

export async function isEnabled(flag: string, attributes: Record<string, string>): Promise<boolean> {
  const gb = new GrowthBook({
    apiHost: process.env.GROWTHBOOK_API_HOST ?? 'https://cdn.growthbook.io',
    clientKey: process.env.GROWTHBOOK_CLIENT_KEY,
    attributes,
  });
  await gb.init({ timeout: 2_000 });
  const on = gb.isOn(flag);
  gb.destroy();
  return on;
}

